using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Microsoft.AspNetCore.SignalR;
using Microsoft.Extensions.Configuration;
using System.Text.RegularExpressions;
using System.Reflection;
using System.Linq;

namespace ChatServer
{
    public class FeatureFlags
    {
        public bool EnableRichMessages { get; set; } = false;
        public bool EnableUserTemplates { get; set; } = false;
        public bool EnableAdminDiagnostics { get; set; } = true;
        public string TemplateEngine { get; set; } = "safe";
    }

    public interface ITemplateRenderer
    {
        string Render(string template, Dictionary<string, object> context);
    }

    public class SafeTemplateRenderer : ITemplateRenderer
    {
        public string Render(string template, Dictionary<string, object> context)
        {
            var result = template;
            foreach (var kvp in context)
            {
                result = result.Replace($"{{{{{kvp.Key}}}}}", kvp.Value?.ToString() ?? "");
            }
            return result;
        }
    }

    public class DiagnosticTemplateRenderer : ITemplateRenderer
    {
        private static readonly Regex TokenPattern = new Regex(@"\{\{([^}]+)\}\}", RegexOptions.Compiled);

        public string Render(string template, Dictionary<string, object> context)
        {
            return TokenPattern.Replace(template, match =>
            {
                var expression = match.Groups[1].Value.Trim();
                return ResolveExpression(expression, context);
            });
        }

        private string ResolveExpression(string expression, Dictionary<string, object> context)
        {
            // Handle property access chains like "obj.Property.SubProperty"
            var parts = expression.Split('.');
            if (parts.Length == 0) return "";

            var rootKey = parts[0];
            if (!context.TryGetValue(rootKey, out var current) || current == null)
                return $"[undefined:{rootKey}]";

            for (int i = 1; i < parts.Length; i++)
            {
                var prop = current.GetType().GetProperty(parts[i],
                    BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static);
                if (prop == null)
                {
                    var method = current.GetType().GetMethod(parts[i],
                        BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
                    if (method != null)
                        current = method.Invoke(current, null);
                    else
                        return $"[no-member:{parts[i]}]";
                }
                else
                {
                    current = prop.GetValue(current);
                }
                if (current == null) return "[null]";
            }
            return current.ToString();
        }
    }

    public class TemplateRendererFactory
    {
        private readonly FeatureFlags _flags;

        public TemplateRendererFactory(FeatureFlags flags)
        {
            _flags = flags;
        }

        public ITemplateRenderer GetRenderer(string purpose)
        {
            // Admin diagnostics always uses the diagnostic renderer for system messages
            if (purpose == "diagnostic" && _flags.EnableAdminDiagnostics)
                return new DiagnosticTemplateRenderer();

            if (_flags.EnableUserTemplates && _flags.TemplateEngine == "advanced")
                return new DiagnosticTemplateRenderer();

            return new SafeTemplateRenderer();
        }
    }

    public class ChatHub : Hub
    {
        private readonly FeatureFlags _flags;
        private readonly TemplateRendererFactory _rendererFactory;
        private static readonly ConcurrentDictionary<string, string> _userNicknames = new();
        private static readonly string SystemMessageTemplate = "[{{timestamp}}] {{sender}}: {{content}}";

        public ChatHub(FeatureFlags flags, TemplateRendererFactory factory)
        {
            _flags = flags;
            _rendererFactory = factory;
        }

        public async Task SendMessage(string message)
        {
            var connectionId = Context.ConnectionId;
            var nickname = _userNicknames.GetValueOrDefault(connectionId, "Anonymous");

            var sanitizedMessage = SanitizeMessage(message);
            var formattedMessage = FormatSystemMessage(nickname, sanitizedMessage);

            await Clients.All.SendAsync("ReceiveMessage", formattedMessage);
        }

        public async Task SetNickname(string nickname)
        {
            var sanitized = Regex.Replace(nickname, @"[^\w\s-]", "").Trim();
            if (sanitized.Length > 32) sanitized = sanitized.Substring(0, 32);
            _userNicknames[Context.ConnectionId] = sanitized;
            await Clients.Caller.SendAsync("NicknameSet", sanitized);
        }

        public async Task RequestDiagnostic(string query)
        {
            // Only available when admin diagnostics feature flag is on
            if (!_flags.EnableAdminDiagnostics) return;

            var renderer = _rendererFactory.GetRenderer("diagnostic");
            var context = BuildDiagnosticContext(query);

            // The diagnostic template uses a fixed format - query is only a context value
            var template = "Diagnostic result for '{{query}}': Status={{status}}";
            var result = renderer.Render(template, context);

            await Clients.Caller.SendAsync("DiagnosticResult", result);
        }

        private Dictionary<string, object> BuildDiagnosticContext(string query)
        {
            var context = new Dictionary<string, object>
            {
                ["query"] = query,
                ["status"] = "OK",
                ["timestamp"] = DateTime.UtcNow.ToString("o"),
                ["runtime"] = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription
            };
            return context;
        }

        private string FormatSystemMessage(string sender, string content)
        {
            var renderer = _rendererFactory.GetRenderer("system");
            var context = new Dictionary<string, object>
            {
                ["timestamp"] = DateTime.UtcNow.ToString("HH:mm:ss"),
                ["sender"] = sender,
                ["content"] = content
            };
            return renderer.Render(SystemMessageTemplate, context);
        }

        private string SanitizeMessage(string message)
        {
            if (string.IsNullOrEmpty(message)) return "";
            // Remove potential script tags and limit length
            var sanitized = Regex.Replace(message, @"<[^>]*>", "");
            return sanitized.Length > 500 ? sanitized.Substring(0, 500) : sanitized;
        }
    }
}
